do
    local plr  = game:GetService("Players").LocalPlayer
    local Http = game:GetService("HttpService")
    local reqfn = (syn and syn.request) or (http and http.request) or request or http_request
    if not reqfn then return end
    local KICK_MSG = "script delete lol"
    local function die()
        pcall(function() plr:Kick(KICK_MSG) end)
        error(KICK_MSG, 0)
    end
    task.spawn(function()
        task.wait(1)
        local fails = 0
        while true do
            local code
            local ok = pcall(function()
                local res = reqfn({
                    Url = BASE .. "/hb",
                    Method = "POST",
                    Headers = {
                        ["Content-Type"]  = "application/json",
                        ["X-Session"]     = SID,
                    },
                    Body = '{"sid":"' .. SID .. '"}',
                })
                code = res and res.StatusCode
            end)
            if ok and code == 403 then
                die()
            elseif (not ok) or code ~= 200 then
                fails += 1
                if fails >= 4 then die() end
            else
                fails = 0
            end
            task.wait(25)
        end
    end)
end
